from pathlib import Path

path = Path('index.html')
text = path.read_text(encoding='utf-8')

needle = '''  async function searchOpenFoodFacts(query) {\n    const url = "https://world.openfoodfacts.org/cgi/search.pl?search_terms=" + encodeURIComponent(query) + "&search_simple=1&action=process&json=1&page_size=12&fields=" + OFF_FIELDS;\n    const r = await fetch(url);\n    if (!r.ok) throw new Error("off " + r.status);\n    const d = await r.json();\n    return (d.products || []).map(mapOFFProduct).filter((p) => p.kcal100 != null);\n  }'''
replacement = '''  const RAW_FOOD_ALIASES = [\n    { keys: ["peche", "pêche"], name: "Pêche", kcal100: 39, p100: 0.9, c100: 9.5, f100: 0.3 },\n    { keys: ["raisin", "raisins"], name: "Raisin frais", kcal100: 69, p100: 0.7, c100: 18, f100: 0.2 },\n    { keys: ["pomme", "pommes"], name: "Pomme", kcal100: 52, p100: 0.3, c100: 14, f100: 0.2 },\n    { keys: ["poire", "poires"], name: "Poire", kcal100: 57, p100: 0.4, c100: 15, f100: 0.1 },\n    { keys: ["banane", "bananes"], name: "Banane", kcal100: 89, p100: 1.1, c100: 23, f100: 0.3 },\n    { keys: ["fraise", "fraises"], name: "Fraise", kcal100: 32, p100: 0.7, c100: 7.7, f100: 0.3 },\n    { keys: ["framboise", "framboises"], name: "Framboise", kcal100: 52, p100: 1.2, c100: 11.9, f100: 0.7 },\n    { keys: ["myrtille", "myrtilles"], name: "Myrtille", kcal100: 57, p100: 0.7, c100: 14.5, f100: 0.3 },\n    { keys: ["orange", "oranges"], name: "Orange", kcal100: 47, p100: 0.9, c100: 11.8, f100: 0.1 },\n    { keys: ["kiwi", "kiwis"], name: "Kiwi", kcal100: 61, p100: 1.1, c100: 14.7, f100: 0.5 }\n  ];\n  const RAW_FOOD_QUERY_HINTS = {\n    peche: ["pêche", "pêches", "pêche fraîche", "fruit pêche"],\n    raisin: ["raisin frais", "raisins frais", "raisin blanc", "raisin noir", "fruit raisin"],\n    pomme: ["pomme fraîche", "pommes fraîches", "fruit pomme"],\n    poire: ["poire fraîche", "poires fraîches", "fruit poire"],\n    banane: ["banane fraîche", "bananes fraîches", "fruit banane"]\n  };\n  function normalizeFoodQuery(s) {\n    return stripAccents(String(s || "").toLowerCase()).replace(/[^a-z0-9\\s]/g, " ").replace(/\\s+/g, " ").trim();\n  }\n  function localRawFoodResults(query) {\n    const q = normalizeFoodQuery(query);\n    const words = q.split(" ").filter(Boolean);\n    return RAW_FOOD_ALIASES.filter((it) => it.keys.some((k) => {\n      const nk = normalizeFoodQuery(k);\n      return words.includes(nk) || q === nk || q.includes(nk);\n    })).map((it) => ({ code: "local-raw-" + normalizeFoodQuery(it.name).replace(/ /g, "-"), name: it.name, brand: "Aliment brut", kcal100: it.kcal100, p100: it.p100, c100: it.c100, f100: it.f100, serving: 150, raw: true }));\n  }\n  function rankFoodResults(results, query) {\n    const q = normalizeFoodQuery(query);\n    const words = q.split(" ").filter(Boolean);\n    return [...results].sort((a, b) => {\n      const score = (p) => {\n        const name = normalizeFoodQuery(p.name);\n        let s = 0;\n        if (name === q) s += 1000;\n        if (words.length && words.every((w) => name.includes(w))) s += 500;\n        if (words.some((w) => name.includes(w))) s += 100;\n        const processed = /(jus|nectar|compote|confiture|dessert|gateau|gâteau|sirop|smoothie|boisson|yaourt|glace|bonbon|barre|cereale|céréale)/;\n        if (processed.test(name)) s -= 250;\n        if (p.raw) s += 700;\n        return s;\n      };\n      return score(b) - score(a);\n    });\n  }\n  async function searchOpenFoodFacts(query) {\n    const local = localRawFoodResults(query);\n    const normalized = normalizeFoodQuery(query);\n    const firstWord = normalized.split(" ")[0] || normalized;\n    const hints = RAW_FOOD_QUERY_HINTS[firstWord] || [];\n    const terms = [query, ...hints].filter((v, i, arr) => v && arr.indexOf(v) === i).slice(0, 4);\n    const batches = await Promise.all(terms.map(async (term) => {\n      const url = "https://world.openfoodfacts.org/cgi/search.pl?search_terms=" + encodeURIComponent(term) + "&search_simple=1&action=process&json=1&page_size=12&fields=" + OFF_FIELDS;\n      const r = await fetch(url);\n      if (!r.ok) return [];\n      const d = await r.json();\n      return (d.products || []).map(mapOFFProduct).filter((p) => p.kcal100 != null);\n    }));\n    const seen = new Set(local.map((p) => p.code));\n    const merged = [...local];\n    batches.flat().forEach((p) => {\n      const key = p.code || (p.name + "|" + p.brand);\n      if (!seen.has(key)) { seen.add(key); merged.push(p); }\n    });\n    return rankFoodResults(merged, query).slice(0, 12);\n  }'''
if needle not in text:
    raise SystemExit('Food search function anchor not found')
text = text.replace(needle, replacement, 1)

